  assert.equal(collides(ball, brick), true);
});

test('collides: ball clearly away => no collision', () => {
  const ball = { x: 300, y: 300, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), false);
});

test('collides: edge contact (radius) detected', () => {
  const ball = { x: 85, y: 100, r: 8 }; // right edge of the ball at 93 > 90
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('step: bounce off the left wall', () => {
  const state = createState(1);
  state.ball = { x: 2, y: 200, r: 7, vx: -300, vy: 0 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx > 0, 'horizontal velocity should flip to the right');
});

test('step: ball exiting through the bottom => lost', () => {
  const state = createState(1);
  state.ball = { x: 320, y: belowField(), r: 7, vx: 0, vy: 400 };
  const lost = step(state, 1 / 60);
  assert.equal(lost, true);
});

test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

// --- New tests for Issue #1 ---

test('brick collision: top face bounce', () => {
  const state = createState(1);
  const brick = state.bricks[0]; // TOP row, first brick
  brick.alive = true;
  // Ball coming from below, hitting the top of the brick
  // Ball center at (brick.x + brick.w/2, brick.y + brick.h + ball.r - 1)
  // Moving UP (vy < 0)
  state.ball = {
    x: brick.x + brick.w / 2,
    y: brick.y + brick.h + 6,
    r: 7,
    vx: 0,
    vy: -200,
  };
  // We need a way to trigger the collision. If it's in step(), we call step().
  // For now, we'll assume it's handled in step() in the final implementation.
  step(state, 0.01); 
  // After step, it should have hit and bounced.
  // Since it's a top hit, vy should be positive.
  assert.ok(state.ball.vy > 0, 'vy should flip to DOWN after hitting brick top');
  assert.equal(state.ball.vx, 0, 'vx should remain unchanged');
});

test('brick collision: bottom face bounce', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  brick.alive = true;
  // Ball coming from above, hitting the bottom of the brick
  state.ball = {
    x: brick.x + brick.w / 2,
    y: brick.y - 6,
    r: 7,
    vx: 0,
    vy: 200,
  };
  step(state, 0.01);
  assert.ok(state.ball.vy < 0, 'vy should flip to UP after hitting brick bottom');
});

test('brick collision: side face bounce', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  brick.alive = true;
  // Ball coming from left, hitting the left face of the brick
  state.ball = {
    x: brick.x - 6,
    y: brick.y + brick.h / 2,
    r: 7,
    vx: 200,
    vy: 0,
  };
  step(state, 0.01);
  assert.ok(state.ball.vx < 0, 'vx should flip to LEFT after hitting brick left face');
});

test('brick collision: corner bounce', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  brick.alive = true;
  // Ball hitting exactly the corner (equal penetration)
  // We'll position it so it's barely overlapping both
  state.ball = {
    x: brick.x - 6, 
    y: brick.y - 6,
    r: 7,
    vx: 200,
    vy: 200,
  };
  step(state, 0.01);
  assert.ok(state.ball.vx < 0 && state.ball.vy < 0, 'both vx and vy should flip on corner hit');
});

test('brick collision: push out to prevent sticky bounce', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  brick.alive = true;
  state.ball = {
    x: brick.x + brick.w / 2,
    y: brick.y + brick.h + 2, // deep penetration
    r: 7,
    vx: 0,
    vy: -200,
  };
  step(state, 0.01);
  // The ball should be pushed out of the brick
  assert.ok(!collides(state.ball, brick), 'ball should be pushed out of the brick after bounce');
});

test('brick collision: no double flip on neighbours', () => {
  const state = createState(1);
  // Two bricks side by side
  const b1 = state.bricks[0];
  const b2 = state.bricks[1];
  b1.alive = true;
  b2.alive = true;
  // Ball hitting exactly the seam between them
  state.ball = {
    x: b1.x + b1.w, 
    y: b1.y + b1.h / 2,
    r: 7,
    vx: 200,
    vy: 0,
  };
  step(state, 0.01);
  assert.ok(state.ball.vx < 0, 'vx should be flipped exactly once, even if hitting two bricks');
});

test('brick collision: tunnelling detection', () => {
  const state = createState(6); // Level 6 has high speed
  const brick = state.bricks[0];
  brick.alive = true;
  // Set ball position such that it would jump over the brick in one step
  // BRICK_H = 20, BALL_R = 7. Total height = 34.
  // speed = ballSpeed(6) = 260 + 5*90 = 710 px/s.
  // dt = 0.05s -> dist = 35.5 px.
  state.ball = {
    x: brick.x + brick.w / 2,
    y: brick.y - 10, // just above the brick
    r: 7,
    vx: 0,
    vy: 710, 
  };
  step(state, 0.05); 
  assert.ok(state.ball.vy < 0, 'ball should bounce even if it would have tunneled through');
});

function belowField() {
  return 500;
}

