export function step(state, dt) {
  const { ball, paddle } = state;
  const oldX = ball.x;
  const oldY = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // ... wall/paddle bounces ...

  // Brick collisions
  for (const brick of state.bricks) {
    if (!brick.alive) continue;

    // Tunnelling check: if the ball moved more than its diameter + brick height/width, 
    // it might have skipped. A simple way is to check if the segment intersects the brick.
    // But let's use a simpler approach: sub-stepping if the movement is too large.
    // Or just check the segment.

