        const overlapL = (ball.x + ball.r) - brick.x;
        const overlapR = (brick.x + brick.w) - (ball.x - ball.r);
        const overlapT = (ball.y + ball.r) - brick.y;
        const overlapB = (brick.y + brick.h) - (ball.y - ball.r);

        const minX = Math.min(overlapL, overlapR);
        const minY = Math.min(overlapT, overlapB);

        if (minX < minY) {
          if (overlapL < overlapR) {
            ball.vx = -Math.abs(ball.vx);
            ball.x = brick.x - ball.r;
          } else {
            ball.vx = Math.abs(ball.vx);
            ball.x = brick.x + brick.w + ball.r;
          }
        } else if (minY < minX) {
          if (overlapT < overlapB) {
            ball.vy = -Math.abs(ball.vy);
            ball.y = brick.y - ball.r;
          } else {
            ball.vy = Math.abs(ball.vy);
            ball.y = brick.y + brick.h + ball.r;
          }
        } else {
          // Corner hit
          ball.vx = -ball.vx;
          ball.vy = -ball.vy;
          if (overlapL < overlapR) ball.x = brick.x - ball.r; else ball.x = brick.x + brick.w + ball.r;
          if (overlapT < overlapB) ball.y = brick.y - ball.r; else ball.y = brick.y + brick.h + ball.r;
        }

        brick.alive = false;
        state.combo += 1;
        state.score += scoreForBrick(brick, state.combo);
      }
    }
  }

  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

// --- Rendering (DOM) -------------------------------------------------------

export function frame(ctx, state) {
  // Background
  ctx.fillStyle = palette.background;
  ctx.fillRect(0, 0, WIDTH, HEIGHT);

  // Bricks
  for (const brick of state.bricks) {
    if (!brick.alive) continue;

    ctx.fillStyle = brickColor(brick.row);
    ctx.fillRect(brick.x, brick.y, brick.w, brick.h);
  }

  // Paddle — color hard-coded instead of using the palette (inconsistency #6).
  ctx.fillStyle = '#00e5ff';
  ctx.fillRect(state.paddle.x, state.paddle.y, state.paddle.w, state.paddle.h);

  // Ball — also hard-coded (#6).
